/// The filter's error constant: E · (1 + 2u)^5 with E = 160u + 772u^2 + 1184u^3 + 1138u^4 + 766u^5
/// + 356u^6 + 112u^7 + 22u^8 + 2u^9, the result's unit error (header), rounded up to an `f64`:
/// 5629499534213130 · 2^-98.
const ERROR: f64 = f64::from_bits(0x3d14_0000_0000_000a);

/// `round_rational`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify
/// it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(x: i128, y: i128, v: i128, q: P2, cx: i128, cy: i128, w: i128) -> Option<Sign> {
    let x = rounded_f64(x, 124)?;
    let v = rounded_f64(v, 83)?;
    let q_x = exact_f64(q.x);
    let ux_1 = v * q_x;
    let ux = x - ux_1;
    let y = rounded_f64(y, 124)?;
    let q_y = exact_f64(q.y);
    let uy_1 = v * q_y;
    let uy = y - uy_1;
    let w = rounded_f64(w, 83)?;
    let tx_1 = w * x;
    let tx_2 = w * v;
    let tx_3 = tx_2 * q_x;
    let tx_4 = tx_1 + tx_3;
    let cx = rounded_f64(cx, 124)?;
    let tx_5 = v * cx;
    let tx_6 = tx_4 - tx_5;
    let tx_7 = v * cx;
    let tx = tx_6 - tx_7;
    let ty_1 = w * y;
    let ty_2 = w * v;
    let ty_3 = ty_2 * q_y;
    let ty_4 = ty_1 + ty_3;
    let cy = rounded_f64(cy, 124)?;
    let ty_5 = v * cy;
    let ty_6 = ty_4 - ty_5;
    let ty_7 = v * cy;
    let ty = ty_6 - ty_7;
    let s_1 = ux * tx;
    let s_2 = uy * ty;
    let s = s_1 + s_2;
    let m_x = largest_magnitude([q_x]);
    let m_y = largest_magnitude([q_y]);
    let m_p = largest_magnitude([x, y]);
    let m_v = largest_magnitude([v]);
    let m_c = largest_magnitude([cx, cy]);
    let m_w = largest_magnitude([w]);
    let scale = larger(m_p * m_v * m_c, m_p * m_p * m_w);
    let scale = larger(scale, m_y * m_v * m_v * m_c);
    let scale = larger(scale, m_y * m_p * m_v * m_w);
    let scale = larger(scale, m_y * m_y * m_v * m_v * m_w);
    let scale = larger(scale, m_x * m_v * m_v * m_c);
    let scale = larger(scale, m_x * m_p * m_v * m_w);
    let scale = larger(scale, m_x * m_x * m_v * m_v * m_w);
    decide(s, ERROR, scale)
}

/// `round_rational`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(x: i128, y: i128, v: i128, q: P2, cx: i128, cy: i128, w: i128) -> Option<I384> {
    let x = within(x, 124)?;
    let v = within(v, 83)?;
    let q_x = q.x.get();
    let ux_1 = v.checked_mul(i128::from(q_x))?;
    let ux = x.checked_sub(ux_1)?;
    let y = within(y, 124)?;
    let q_y = q.y.get();
    let uy_1 = v.checked_mul(i128::from(q_y))?;
    let uy = y.checked_sub(uy_1)?;
    let w = within(w, 83)?;
    let tx_1 = I256::product_i128(w, x)?;
    let tx_2 = I256::product_i128(w, v)?;
    let tx_3 = tx_2.checked_mul_i128(i128::from(q_x))?;
    let tx_4 = tx_1.checked_add(&tx_3)?;
    let cx = within(cx, 124)?;
    let tx_5 = I256::product_i128(v, cx)?;
    let tx_6 = tx_4.checked_sub(&tx_5)?;
    let tx_7 = I256::product_i128(v, cx)?;
    let tx = tx_6.checked_sub(&tx_7)?;
    let ty_1 = I256::product_i128(w, y)?;
    let ty_2 = I256::product_i128(w, v)?;
    let ty_3 = ty_2.checked_mul_i128(i128::from(q_y))?;
    let ty_4 = ty_1.checked_add(&ty_3)?;
    let cy = within(cy, 124)?;
    let ty_5 = I256::product_i128(v, cy)?;
    let ty_6 = ty_4.checked_sub(&ty_5)?;
    let ty_7 = I256::product_i128(v, cy)?;
    let ty = ty_6.checked_sub(&ty_7)?;
    let s_1 = tx.resize::<6>()?.checked_mul_i128(ux)?;
    let s_2 = ty.resize::<6>()?.checked_mul_i128(uy)?;
    let s = s_1.checked_add(&s_2)?;
    Some(s)
}

/// `round_rational`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(x: i128, y: i128, v: i128, q: P2, cx: i128, cy: i128, w: i128) -> Option<Sign> {
    value(x, y, v, q, cx, cy, w).map(|v| v.signum())
}
